		contents: "---\n/*\n * specorator-template-version: 1\n *\n * Dynamic route for the whole site namespace (docs/DESIGN.md §5.5, §5.7). One\n * static page per committed snapshot **listing** route (e.g. `/books`) AND one\n * per published entry **detail** route (e.g. `/books/dune`), all in the single\n * `[...slug]` namespace. `getStaticPaths()` enumerates the `snapshots`\n * collection: each snapshot yields its listing page plus a detail page per entry\n * (the entry's authoritative, collision-checked `route` from the plugin's route\n * table — C8/FR-15). Listing pages dispatch to a view component via the stable\n * registry barrel (`registry.ts`) using `render.component`, defaulting to the\n * view `type` when the binding is `'auto'` (§5.6); detail pages render the\n * `detail` component with the entry body at core fidelity (FR-21, D8). The\n * registry barrel keeps the file set stable so new components dodge Astro's\n * new-file HMR gap (D9).\n */\nimport { getCollection } from 'astro:content';\nimport { resolveLayout, resolveView } from '../registry';\nimport type { EntrySnapshot, ViewSnapshot } from '../content/schema';\n\nexport async function getStaticPaths() {\n\t// Astro extracts `getStaticPaths` into an isolated module, so it cannot rely\n\t// on frontmatter-scope helpers — keep the slug stripper inline. The\n\t// `[...slug]` param is slash-relative, so drop the route's leading slash.\n\tconst toParam = (route: string): string => route.replace(/^\\/+/, '');\n\n\tconst entries = await getCollection('snapshots');\n\tconst paths: {\n\t\tparams: { slug: string };\n\t\tprops: { snapshot: ViewSnapshot; entry?: EntrySnapshot };\n\t}[] = [];\n\n\tfor (const collectionEntry of entries) {\n\t\tconst snapshot = collectionEntry.data;\n\t\t// The listing page (the collection entry id is the listing route).\n\t\tpaths.push({ params: { slug: toParam(collectionEntry.id) }, props: { snapshot } });\n\n\t\t// One detail page per published entry, addressed by the entry's route.\n\t\tfor (const group of snapshot.groups) {\n\t\t\tfor (const entry of group.entries) {\n\t\t\t\tpaths.push({ params: { slug: toParam(entry.route) }, props: { snapshot, entry } });\n\t\t\t}\n\t\t}\n\t}\n\n\treturn paths;\n}\n\ninterface Props {\n\tsnapshot: ViewSnapshot;\n\t/** Present for a detail route; absent for a listing route. */\n\tentry?: EntrySnapshot;\n}\n\nconst { snapshot, entry } = Astro.props;\nconst isDetail = entry !== undefined;\n\n// Listing: an explicit component binding wins; `'auto'` falls back to the view\n// type. Detail: always the `detail` component (FR-21).\nconst componentName = isDetail\n\t? 'detail'\n\t: snapshot.render.component && snapshot.render.component !== 'auto'\n\t\t? snapshot.render.component\n\t\t: snapshot.view.type;\n\nconst View = resolveView(componentName);\nconst layoutName =\n\tsnapshot.render.layout && snapshot.render.layout !== 'auto'\n\t\t? snapshot.render.layout\n\t\t: 'BaseLayout';\nconst Layout = resolveLayout(layoutName);\nconst title = isDetail ? entry.basename : snapshot.view.name;\n---\n\n<Layout title={title}>\n\t{\n\t\tisDetail ? (\n\t\t\t<View entry={entry} snapshot={snapshot} />\n\t\t) : (\n\t\t\t<>\n\t\t\t\t<header class=\"sp-listing-header\">\n\t\t\t\t\t<h1>{snapshot.view.name}</h1>\n\t\t\t\t</header>\n\t\t\t\t<View snapshot={snapshot} />\n\t\t\t</>\n\t\t)\n\t}\n</Layout>\n\n<style>\n\t.sp-listing-header h1 {\n\t\tcolor: var(--sp-color-fg);\n\t\tmargin-top: 0;\n\t}\n</style>\n",
